  await page.evaluate(() => chartCheck.update());
  await page.waitForTimeout(100);
  assert.deepEqual(await page.evaluate(() => chartCheck.range()), range);
  assert.equal((await page.evaluate(() => chartCheck.instance())).last, 91);
  await page.evaluate(() => chartCheck.dark());
  await page.waitForTimeout(100);
